package com.termux.app.workspace;
import java.util.*;import java.util.concurrent.Executor;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) public class OfflineDictationTest {
 static class Queue implements Executor {final Deque<Runnable> work=new ArrayDeque<>();public void execute(Runnable r){work.add(r);}void drain(){while(!work.isEmpty())work.remove().run();}}
 static class Capture implements OfflineDictation.Session {int starts,closes,reads;String preview="{\"partial\":\"первое\"}",answer="{\"text\":\"первое слово\"}";Runnable onRead=()->{};int readError;public void start(){starts++;}public int read(short[] b){reads++;onRead.run();return readError==0?128:readError;}public boolean accept(short[] b,int n){return reads>1;}public String result(){return answer;}public String partial(){return preview;}public String finish(){return answer;}public void close(){closes++;}}
 static class Events implements DictationBackend.Listener {List<String> values=new ArrayList<>();public void ready(){values.add("ready");}public void partial(String t){values.add("partial:"+t);}public void result(String t){values.add("result:"+t);}public void error(String t){values.add("error:"+t);}}
 @Test public void partialThenEndpointResultAndCleanupOnce(){Queue work=new Queue(),ui=new Queue();Capture c=new Capture();Events e=new Events();OfflineDictation d=new OfflineDictation(cancel->c,work,ui::execute);d.start(e);d.start(e);work.drain();ui.drain();assertEquals(Arrays.asList("ready","partial:первое","result:первое слово"),e.values);assertEquals(1,c.starts);assertEquals(1,c.closes);}
 @Test public void cancellationBeforePreparationDoesNotOpenMicrophone(){Queue work=new Queue();Events e=new Events();OfflineDictation d=new OfflineDictation(cancel->{throw new AssertionError("cancelled model must not open");},work,Runnable::run);d.start(e);d.cancel();work.drain();assertTrue(e.values.isEmpty());}
 @Test public void cancellationDuringPreparationClosesWithoutStarting(){Queue work=new Queue();Capture c=new Capture();Events e=new Events();OfflineDictation[] d=new OfflineDictation[1];d[0]=new OfflineDictation(cancel->{d[0].cancel();return c;},work,Runnable::run);d[0].start(e);work.drain();assertEquals(0,c.starts);assertEquals(1,c.closes);assertTrue(e.values.isEmpty());}
 @Test public void manualStopFinalizesButCancelSuppressesQueuedResult(){for(boolean cancel:new boolean[]{false,true}){Queue work=new Queue(),ui=new Queue();Capture c=new Capture();Events e=new Events();OfflineDictation[] d=new OfflineDictation[1];d[0]=new OfflineDictation(ignored->c,work,ui::execute);c.onRead=()->d[0].stop();d[0].start(e);work.drain();if(cancel)d[0].cancel();ui.drain();assertEquals(1,c.closes);if(cancel)assertTrue(e.values.isEmpty());else assertEquals(Collections.singletonList("result:первое слово"),e.values);}}
 @Test public void modelFailureAndReadFailureHaveDistinctStages(){Queue work=new Queue();Events model=new Events();new OfflineDictation(cancel->{throw new java.io.IOException("checksum");},work,Runnable::run).start(model);work.drain();assertTrue(model.values.get(0).contains("model: IOException: checksum"));Capture c=new Capture();c.readError=-3;Events microphone=new Events();new OfflineDictation(cancel->c,work,Runnable::run).start(microphone);work.drain();assertTrue(microphone.values.get(1).contains("microphone: IOException: AudioRecord.read=-3"));assertEquals(1,c.closes);}
 @Test public void invalidDecoderJsonIsAnErrorAndResourcesClose(){Queue work=new Queue();Capture c=new Capture();c.preview="invalid";Events e=new Events();new OfflineDictation(cancel->c,work,Runnable::run).start(e);work.drain();assertTrue(e.values.get(1).startsWith("error:recognition:"));assertEquals(1,c.closes);}
}
